#include "clang/StaticAnalyzer/Core/BugReporter/BugReporter.h"
#include "clang/StaticAnalyzer/Core/BugReporter/BugType.h"
#include "clang/StaticAnalyzer/Checkers/Taint.h"
#include "clang/StaticAnalyzer/Core/Checker.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/CallEvent.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/CheckerContext.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/Environment.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/ProgramState.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/ProgramStateTrait.h"
#include "clang/StaticAnalyzer/Core/PathSensitive/SymExpr.h"
#include "clang/StaticAnalyzer/Frontend/CheckerRegistry.h"
#include "clang/AST/RecursiveASTVisitor.h"
#include "clang/AST/StmtVisitor.h"
#include "llvm/Support/raw_ostream.h"
#include "clang/StaticAnalyzer/Checkers/utility.h"

#include "clang/AST/Decl.h"
#include "clang/AST/Expr.h"

using namespace clang;
using namespace ento;
using namespace taint;

// Program state map for local-variable initialization status.
// The mapping: VarDecl* -> bool (true means initialized, false means uninitialized).
REGISTER_MAP_WITH_PROGRAMSTATE(UninitVarMap, const VarDecl*, bool)

namespace {

class SAGenTestChecker : public Checker<check::PostStmt<DeclStmt>,
                                          check::Bind,
                                          check::PreStmt<ReturnStmt>> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "Uninitialized Variable", "Uninitialized local usage")) {}

  // Called after a declaration statement is processed.
  void checkPostStmt(const DeclStmt *DS, CheckerContext &C) const;

  // Called when a value is bound to a variable.
  void checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const;

  // Called before a return statement is processed.
  void checkPreStmt(const ReturnStmt *RS, CheckerContext &C) const;
};

// checkPostStmt: Processes declaration statements to record "ret" variables
// that are declared without an initializer.
void SAGenTestChecker::checkPostStmt(const DeclStmt *DS, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  for (const Decl *D : DS->decls()) {
    if (const VarDecl *VD = dyn_cast<VarDecl>(D)) {
      if (!VD->hasInit())
        State = State->set<UninitVarMap>(VD, false);
    }
  }
  C.addTransition(State);
}

// checkBind: Processes assignments to update local initialization status.
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  if (const auto *BO = dyn_cast<BinaryOperator>(S)) {
    if (BO->isAssignmentOp()) {
      const Expr *LHS = BO->getLHS()->IgnoreParenImpCasts();
      if (const auto *DRE = dyn_cast<DeclRefExpr>(LHS)) {
        if (const auto *VD = dyn_cast<VarDecl>(DRE->getDecl()))
          State = State->set<UninitVarMap>(VD, true);
      }
    }
  }
  C.addTransition(State);
}

static const DeclRefExpr *findUninitializedReturnUse(const Stmt *S,
                                                       ProgramStateRef State,
                                                       bool AddressOnly = false) {
  if (const auto *DRE = dyn_cast<DeclRefExpr>(S)) {
    if (!AddressOnly) {
      if (const auto *VD = dyn_cast<VarDecl>(DRE->getDecl())) {
        const bool *Initialized = State->get<UninitVarMap>(VD);
        if (Initialized && !*Initialized)
          return DRE;
      }
    }
    return nullptr;
  }

  if (const auto *BO = dyn_cast<BinaryOperator>(S)) {
    if (BO->getOpcode() == BO_Assign)
      return findUninitializedReturnUse(BO->getRHS(), State);
  }

  const bool ChildAddressOnly =
      AddressOnly || (isa<UnaryOperator>(S) &&
                      cast<UnaryOperator>(S)->getOpcode() == UO_AddrOf);
  for (const Stmt *Child : S->children()) {
    if (const DeclRefExpr *Use =
            findUninitializedReturnUse(Child, State, ChildAddressOnly))
      return Use;
  }
  return nullptr;
}

// checkPreStmt: Report an uninitialized local when its value contributes to a
// return expression, including through casts or other value expressions.
void SAGenTestChecker::checkPreStmt(const ReturnStmt *RS, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const Expr *RetExpr = RS->getRetValue();
  if (!RetExpr)
    return;

  const DeclRefExpr *Use = findUninitializedReturnUse(RetExpr, State);
  if (!Use)
    return;

  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;
  auto Report = std::make_unique<PathSensitiveBugReport>(
      *BT, "Uninitialized local variable used", N);
  Report->addRange(Use->getSourceRange());
  C.emitReport(std::move(Report));
  C.addTransition(State);
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker", 
      "Detects usage of uninitialized local variable 'ret'", 
      "");
}

